#[derive(Debug, Clone, PartialEq, Eq)]
enum Exp {
    Const(i32),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

fn eval(e: &Exp, store: &std::collections::HashMap<String, i32>) -> i32 {
    match e {
        Exp::Const(val) => *val,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(left, right) => eval(left, store) + eval(right, store),
        Exp::Mult(left, right) => eval(left, store) * eval(right, store),
    }
}

fn optimize(e: Exp) -> Exp {
    match e {
        // Multiplication optimizations
        Exp::Mult(left, right) => {
            match (*left, *right) {
                // If either operand is 0, replace with Const(0)
                (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),
                
                // If left is 1, replace with right operand
                (Exp::Const(1), right_exp) => right_exp,
                
                // If right is 1, replace with left operand
                (left_exp, Exp::Const(1)) => left_exp,
                
                // If both are constants, compute product
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a * b),
                
                // Otherwise, return original expression
                (left_exp, right_exp) => Exp::Mult(Box::new(left_exp), Box::new(right_exp)),
            }
        }
        
        // Addition optimizations
        Exp::Plus(left, right) => {
            match (*left, *right) {
                // If either operand is 0, replace with other operand
                (Exp::Const(0), right_exp) => right_exp,
                (left_exp, Exp::Const(0)) => left_exp,
                
                // If both are constants, compute sum
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a + b),
                
                // Otherwise, return original expression
                (left_exp, right_exp) => Exp::Plus(Box::new(left_exp), Box::new(right_exp)),
            }
        }
        
        // For Const and Var, return unchanged
        Exp::Const(_) | Exp::Var(_) => e,
    }
}

